   await d.getByRole('button',{name:'CADASTRAR',exact:true}).click();await page.getByRole('alertdialog').getByRole('button',{name:'Confirmar',exact:true}).click();await d.waitFor({state:'hidden'});let records=(await snap())[sub?'subcategories':'categories'],record=records.find(r=>r.name==='ÁGUA MINERAL');assert.ok(record);const id=record.id;
   await page.getByPlaceholder('Pesquisar...').fill('ÁGUA MINERAL');const row=page.locator('tr[data-record-id="'+id+'"]');await row.waitFor();await row.getByRole('button',{name:/Editar/}).click();d=page.getByRole('dialog');input=d.getByLabel(sub?'Nome da Subcategoria 1':'Nome da Categoria 1',{exact:true});if(sub)assert.equal(await d.locator('select').inputValue(),uuid(301));await input.fill('  café\t com   leite  ');await d.getByRole('button',{name:'Salvar alterações',exact:true}).click();await page.getByRole('alertdialog').getByRole('button',{name:'Confirmar',exact:true}).click();await d.waitFor({state:'hidden'});record=(await snap())[sub?'subcategories':'categories'].find(r=>r.id===id);assert.equal(record.name,'CAFÉ COM LEITE');
