   await field.fill('CAMPO PRIMEIRO');await d.getByRole('button',{name:add,exact:true}).click();await d.getByLabel(label+'2',{exact:true}).fill('CAMPO SEGUNDO');if(sub)await d.locator('select').nth(1).selectOption({label:'CATEGORIA QA 002'});await d.getByRole('button',{name:'Remover',exact:true}).first().click();field=d.getByLabel(label+'1',{exact:true});assert.equal(await field.inputValue(),'CAMPO SEGUNDO');assert.equal(await field.getAttribute('id'),sub?'subcategory-name-0':'category-name-0');
